// ============================================================================
// Pattern Breaker — Phase 1 detector, JavaScript port for n8n Code node.
// Faithful, deterministic port of detector/detector.py. No LLM. No randomness.
// Thresholds are inlined (kept in sync with config/thresholds.json).
// Input:  items[0].json.text
// Output: one item with { text, flagged, metrics, flags, flagged_spans }
// ============================================================================

const CFG = {
  sentence_rhythm: { min_sentences: 4, cv_flag_below: 0.35, autocorr_lag1_flag_above: 0.55 },
  burstiness: { min_sentences: 4, sentence_burstiness_flag_below: 0.45, word_burstiness_flag_below: 0.30 },
  sentence_structure: { min_sentences: 4, opening_bigram_repeat_ratio_flag_above: 0.30, same_first_token_run_flag_at: 3 },
  paragraph_pattern: { min_paragraphs: 3, length_cv_flag_below: 0.25, parallel_opening_ratio_flag_above: 0.50 },
  ngram_formula: { ngram_sizes: [3, 4, 5], min_repeats_to_flag: 2, ignore_if_all_stopwords: true },
  transition_formula: {
    max_total_ratio_flag_above: 0.15, max_single_connective_count: 2,
    connectives: ["moreover","furthermore","additionally","in addition","in conclusion","overall","ultimately","notably","importantly","consequently","as a result","in summary","to summarize","in essence","essentially","it is worth noting","it's worth noting","it is important to note","when it comes to","in today's world","in the world of","nestled","whether you're","whether you are","look no further","rest assured"]
  },
  engine: { max_words: 5000, min_words_to_analyze: 40, verify_max_passes: 3 }
};

const STOPWORDS = new Set(["the","a","an","and","or","but","of","to","in","on","for","with","at","by","from","as","is","are","was","were","be","been","being","it","its","this","that","these","those","you","your","we","our","they","their","he","she","his","her","i","me","my"]);
const ABBREV = new Set(["mr","mrs","ms","dr","st","vs","etc","e.g","i.e","u.s","u.k"]);

const WORD_RE = /[A-Za-z0-9']+/g;
function words(s) { return (s.match(WORD_RE) || []); }

// --- sentence split with char offsets (mirror of Python _split_sentences) ---
function splitSentences(text) {
  const out = [];
  const re = /([.!?]+)(\s+|$)/g;
  let start = 0, m;
  const n = text.length;
  while ((m = re.exec(text)) !== null) {
    const end = m.index + m[1].length;
    const chunk = text.slice(start, end);
    const stripped = chunk.trim();
    if (stripped) {
      const tail = words(chunk.slice(-6).toLowerCase());
      const last = tail.length ? tail[tail.length - 1] : "";
      if (ABBREV.has(last) && end < n) { continue; }
      const realStart = start + (chunk.length - chunk.replace(/^\s+/, "").length);
      out.push({ text: text.slice(realStart, end).trim(), start: realStart, end });
    }
    start = re.lastIndex;
  }
  if (start < n && text.slice(start).trim()) {
    const rest = text.slice(start);
    const realStart = start + (rest.length - rest.replace(/^\s+/, "").length);
    out.push({ text: text.slice(realStart).trim(), start: realStart, end: n });
  }
  return out;
}

function parse(text) {
  // paragraph bounds
  const paraBounds = [];
  let pos = 0;
  for (const part of text.split(/\n\s*\n/)) {
    const s = text.indexOf(part, pos);
    const e = s + part.length;
    paraBounds.push([s, e]);
    pos = e;
  }
  const paraOf = (off) => {
    for (let i = 0; i < paraBounds.length; i++) if (paraBounds[i][0] <= off && off < paraBounds[i][1]) return i;
    return paraBounds.length - 1;
  };
  const sents = [];
  for (const s of splitSentences(text)) {
    const w = words(s.text.toLowerCase());
    if (!w.length) continue;
    const first = w[0];
    const bigram = w.length >= 2 ? w.slice(0, 2).join(" ") : first;
    sents.push({ text: s.text, start: s.start, end: s.end, para: paraOf(s.start),
      wc: w.length, first, bigram });
  }
  return sents;
}

// --- math helpers ---
const mean = xs => xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : 0;
function variance(xs) { if (xs.length < 2) return 0; const m = mean(xs); return xs.reduce((a, x) => a + (x - m) ** 2, 0) / (xs.length - 1); }
const std = xs => Math.sqrt(variance(xs));
function cv(xs) { const m = mean(xs); return m === 0 ? 0 : std(xs) / m; }
function autocorr(xs) {
  const n = xs.length; if (n < 3) return 0;
  const m = mean(xs);
  const denom = xs.reduce((a, x) => a + (x - m) ** 2, 0);
  if (denom === 0) return 0;
  let num = 0; for (let i = 0; i < n - 1; i++) num += (xs[i] - m) * (xs[i + 1] - m);
  return num / denom;
}
function burstiness(xs) {
  const mu = mean(xs), sigma = std(xs);
  if (sigma + mu === 0) return 0;
  const b = (sigma - mu) / (sigma + mu);
  return Math.max(0, (b + 1) / 2);
}
const round = (x, d = 4) => Number(x.toFixed(d));

// --- detectors ---
function detectRhythm(sents, flags) {
  const c = CFG.sentence_rhythm;
  if (sents.length < c.min_sentences) return;
  const lengths = sents.map(s => s.wc);
  const _cv = cv(lengths), ac = autocorr(lengths);
  const span = [sents[0].start, sents[sents.length - 1].end];
  if (_cv < c.cv_flag_below)
    flags.push({ factor: "sentence_rhythm", scope: "document", reason: `Sentence-length CV ${round(_cv, 3)} below ${c.cv_flag_below} — sentences too uniform.`, metric: round(_cv), threshold: c.cv_flag_below, span_start: span[0], span_end: span[1], span_text: "[document]" });
  if (ac > c.autocorr_lag1_flag_above)
    flags.push({ factor: "sentence_rhythm", scope: "document", reason: `Sentence-length lag-1 autocorrelation ${round(ac, 3)} exceeds ${c.autocorr_lag1_flag_above} — repetitive rhythm.`, metric: round(ac), threshold: c.autocorr_lag1_flag_above, span_start: span[0], span_end: span[1], span_text: "[document]" });
}

function detectBurstiness(sents, text, flags) {
  const c = CFG.burstiness;
  if (sents.length < c.min_sentences) return;
  const sb = burstiness(sents.map(s => s.wc));
  const wb = burstiness(words(text).map(w => w.length));
  const span = [sents[0].start, sents[sents.length - 1].end];
  if (sb < c.sentence_burstiness_flag_below)
    flags.push({ factor: "burstiness", scope: "document", reason: `Sentence burstiness ${round(sb, 3)} below ${c.sentence_burstiness_flag_below} — lacks short/long variation.`, metric: round(sb), threshold: c.sentence_burstiness_flag_below, span_start: span[0], span_end: span[1], span_text: "[document]" });
  if (wb < c.word_burstiness_flag_below)
    flags.push({ factor: "burstiness", scope: "document", reason: `Word-length burstiness ${round(wb, 3)} below ${c.word_burstiness_flag_below} — word lengths too even.`, metric: round(wb), threshold: c.word_burstiness_flag_below, span_start: span[0], span_end: span[1], span_text: "[document]" });
}

function detectStructure(sents, flags) {
  const c = CFG.sentence_structure;
  if (sents.length < c.min_sentences) return;
  const counts = {};
  for (const s of sents) counts[s.bigram] = (counts[s.bigram] || 0) + 1;
  let best = null, freq = 0;
  for (const [k, v] of Object.entries(counts)) if (v > freq) { best = k; freq = v; }
  const ratio = freq / sents.length;
  if (ratio > c.opening_bigram_repeat_ratio_flag_above && freq >= 2) {
    for (const s of sents) if (s.bigram === best)
      flags.push({ factor: "sentence_structure", scope: "sentence", reason: `Sentence opening '${best}' repeats in ${freq}/${sents.length} sentences (ratio ${round(ratio, 2)} > ${c.opening_bigram_repeat_ratio_flag_above}).`, metric: round(ratio), threshold: c.opening_bigram_repeat_ratio_flag_above, span_start: s.start, span_end: s.end, span_text: s.text });
  }
  // runs of same first token
  let runStart = 0;
  for (let i = 1; i <= sents.length; i++) {
    const same = i < sents.length && sents[i].first === sents[runStart].first;
    if (!same) {
      const runLen = i - runStart;
      if (runLen >= c.same_first_token_run_flag_at)
        for (let j = runStart; j < i; j++)
          flags.push({ factor: "sentence_structure", scope: "sentence", reason: `${runLen} consecutive sentences start with '${sents[runStart].first}'.`, metric: runLen, threshold: c.same_first_token_run_flag_at, span_start: sents[j].start, span_end: sents[j].end, span_text: sents[j].text });
      runStart = i;
    }
  }
}

function detectParagraph(sents, text, flags) {
  const c = CFG.paragraph_pattern;
  const paras = {};
  for (const s of sents) (paras[s.para] = paras[s.para] || []).push(s);
  const ids = Object.keys(paras).map(Number).sort((a, b) => a - b);
  if (ids.length < c.min_paragraphs) return;
  const lengths = ids.map(p => paras[p].length);
  const _cv = cv(lengths);
  const openings = ids.map(p => paras[p][0].bigram);
  const oc = {};
  for (const o of openings) oc[o] = (oc[o] || 0) + 1;
  let parallel = 0;
  for (const v of Object.values(oc)) if (v >= 2) parallel += v;
  const pr = parallel / ids.length;
  if (_cv < c.length_cv_flag_below)
    for (const p of ids) { const b = paras[p];
      flags.push({ factor: "paragraph_pattern", scope: "paragraph", reason: `Paragraph lengths uniform (CV ${round(_cv, 3)} < ${c.length_cv_flag_below}) — mechanical paragraphing.`, metric: round(_cv), threshold: c.length_cv_flag_below, span_start: b[0].start, span_end: b[b.length - 1].end, span_text: text.slice(b[0].start, b[b.length - 1].end) }); }
  if (pr > c.parallel_opening_ratio_flag_above)
    for (const p of ids) { const b = paras[p]; if (oc[b[0].bigram] >= 2)
      flags.push({ factor: "paragraph_pattern", scope: "paragraph", reason: `Paragraph opening '${b[0].bigram}' reused across paragraphs (parallel ratio ${round(pr, 2)} > ${c.parallel_opening_ratio_flag_above}).`, metric: round(pr), threshold: c.parallel_opening_ratio_flag_above, span_start: b[0].start, span_end: b[b.length - 1].end, span_text: text.slice(b[0].start, b[b.length - 1].end) }); }
}

function detectNgram(text, flags) {
  const c = CFG.ngram_formula;
  const toks = [];
  let m;
  const re = /[A-Za-z0-9']+/g;
  while ((m = re.exec(text)) !== null) toks.push({ w: m[0].toLowerCase(), s: m.index, e: m.index + m[0].length });
  const N = toks.length;
  for (const size of c.ngram_sizes) {
    if (N < size) continue;
    const grams = {};
    for (let i = 0; i <= N - size; i++) {
      const slice = toks.slice(i, i + size);
      if (c.ignore_if_all_stopwords && slice.every(t => STOPWORDS.has(t.w))) continue;
      const key = slice.map(t => t.w).join(" ");
      (grams[key] = grams[key] || []).push(i);
    }
    for (const [g, idxs] of Object.entries(grams)) {
      if (idxs.length >= c.min_repeats_to_flag)
        for (const i of idxs)
          flags.push({ factor: "ngram_formula", scope: "span", reason: `${size}-word formula "${g}" repeats ${idxs.length} times.`, metric: idxs.length, threshold: c.min_repeats_to_flag, span_start: toks[i].s, span_end: toks[i + size - 1].e, span_text: text.slice(toks[i].s, toks[i + size - 1].e) });
    }
  }
}

function detectTransition(sents, flags) {
  const c = CFG.transition_formula;
  const conns = c.connectives.map(x => x.toLowerCase());
  const total = sents.length;
  if (!total) return;
  const perConn = {};
  const hits = [];
  for (const s of sents) {
    const low = s.text.toLowerCase().replace(/^\s+/, "");
    for (const conn of conns) {
      if (low.startsWith(conn)) { perConn[conn] = (perConn[conn] || 0) + 1; hits.push([conn, s]); break; }
    }
  }
  const tr = hits.length / total;
  if (tr > c.max_total_ratio_flag_above)
    for (const [conn, s] of hits)
      flags.push({ factor: "transition_formula", scope: "sentence", reason: `Formulaic connective opener '${conn}' — connectives open ${hits.length}/${total} sentences (ratio ${round(tr, 2)} > ${c.max_total_ratio_flag_above}).`, metric: round(tr), threshold: c.max_total_ratio_flag_above, span_start: s.start, span_end: s.end, span_text: s.text });
  for (const [conn, cnt] of Object.entries(perConn))
    if (cnt > c.max_single_connective_count)
      for (const [hc, s] of hits) if (hc === conn)
        flags.push({ factor: "transition_formula", scope: "sentence", reason: `Connective '${conn}' opens ${cnt} sentences (> ${c.max_single_connective_count}).`, metric: cnt, threshold: c.max_single_connective_count, span_start: s.start, span_end: s.end, span_text: s.text });
}

// --- dedup merged spans (mirror of Python _dedup_spans) ---
function dedupSpans(flags) {
  const concrete = flags.filter(f => ["sentence", "paragraph", "span"].includes(f.scope));
  const set = {};
  for (const f of concrete) set[`${f.span_start}:${f.span_end}`] = [f.span_start, f.span_end];
  const ranges = Object.values(set).sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const merged = [];
  for (const [s, e] of ranges) {
    if (merged.length && s <= merged[merged.length - 1][1]) merged[merged.length - 1][1] = Math.max(merged[merged.length - 1][1], e);
    else merged.push([s, e]);
  }
  return merged.map(([s, e]) => {
    const cover = concrete.filter(f => !(f.span_end <= s || f.span_start >= e));
    return { start: s, end: e, factors: [...new Set(cover.map(f => f.factor))].sort(), reasons: cover.map(f => f.reason) };
  });
}

// --- main ---
function detect(text) {
  const w = words(text);
  const sents = parse(text);
  const paras = new Set(sents.map(s => s.para)).size;
  const report = { text, flagged: false, word_count: w.length, sentence_count: sents.length, paragraph_count: paras, metrics: {}, flags: [], flagged_spans: [], notes: [] };
  if (w.length < CFG.engine.min_words_to_analyze) {
    report.notes.push(`Input ${w.length} words below min_words_to_analyze ${CFG.engine.min_words_to_analyze}; detection skipped.`);
    return report;
  }
  const flags = [];
  detectNgram(text, flags);
  detectRhythm(sents, flags);
  detectBurstiness(sents, text, flags);
  detectStructure(sents, flags);
  detectParagraph(sents, text, flags);
  detectTransition(sents, flags);

  const slen = sents.map(s => s.wc);
  const wlen = w.map(x => x.length);
  report.metrics = {
    sentence_length_cv: round(cv(slen)), sentence_length_autocorr_lag1: round(autocorr(slen)),
    sentence_burstiness: round(burstiness(slen)), word_burstiness: round(burstiness(wlen)),
    mean_sentence_length: round(mean(slen), 2)
  };
  report.flags = flags;
  report.flagged = flags.length > 0;
  report.flagged_spans = dedupSpans(flags);
  if (report.flagged && !report.flagged_spans.length)
    report.flagged_spans = sents.map(s => ({ start: s.start, end: s.end, factors: [...new Set(flags.map(f => f.factor))].sort(), reasons: flags.filter(f => f.scope === "document").map(f => f.reason) }));
  return report;
}

// n8n entry point
const input = $input.first().json;
const text = (input.body && input.body.text) || input.text || "";
return [{ json: detect(text) }];

// ============================================================================
// Pattern Breaker — Phase 2 prep (n8n Code node, run once, output multiple items)
// Consumes the Phase-1 DetectionReport, and for EACH flagged span emits one item
// carrying the exact Anthropic payload (hardcoded system prompt + user template,
// deterministic Markov cadence seeds + paragraph shape). Non-flagged input yields
// zero span items but preserves the original text on a passthrough field.
// ============================================================================

// ---- HARDCODED system prompt (verbatim copy of restructurer/restructure.py) --
const SYSTEM_PROMPT = `You are a constrained text-restructuring tool, NOT a writer with creative freedom.

You will receive ONE short flagged text span at a time, plus the exact mechanical
pattern(s) a deterministic detector found in it. Your ONLY job is to break those
patterns while preserving 100% of the meaning.

NON-DEVIATION RULES (violating any is a failure):
1. DO NOT add any fact, name, place, number, date, price, or claim that is not
   already present in the span. Zero new information.
2. DO NOT remove any fact, name, place, number, date, or price that IS present.
   Preserve every entity and every quantity exactly (you may spell a number in
   words, e.g. "3" -> "three", but never change its value).
3. DO NOT add filler, fluff, marketing adjectives, or padding to hit a length.
4. Preserve the original language and tense. If the span is Spanish, answer in
   Spanish. If English, English.

WHAT YOU MUST DO (this is why you exist):
- Break the detected pattern. If sentences were uniform in length, make them
  deliberately UNEVEN. This is mandatory: include at least one VERY SHORT
  sentence (2-5 words) AND at least one LONG sentence (18+ words) in your
  rewrite, so the length variation (burstiness) is high. Do NOT make every
  sentence a similar length. A one- or two-word sentence fragment is allowed if
  it preserves meaning.
- If sentence openings repeated, start each sentence differently.
- If paragraph structure was uniform, VARY it: use the suggested paragraph shape
  (number of paragraphs and sentences each) as a target, without adding content.
- If formulaic connectives (Moreover, Furthermore, Additionally, In conclusion)
  were used, remove or replace them with natural phrasing.
- You are given MARKOV CADENCE SEEDS drawn from the text's own words and a human
  travel corpus. Use them ONLY as inspiration for rhythm and natural connective
  variety. They are NOT facts to insert. Never state anything from a seed as a
  claim about the subject.

OUTPUT FORMAT:
Return ONLY the rewritten span as plain text. No preamble, no explanation, no
quotes around it, no markdown fences.`;

const USER_TEMPLATE = (span, reasons, shape, seeds) =>
`FLAGGED SPAN (rewrite this, break the pattern, keep every fact):
---
${span}
---

DETECTED PATTERNS TO BREAK:
${reasons}

TARGET PARAGRAPH SHAPE (approximate, do NOT pad to reach it):
${shape}

MARKOV CADENCE SEEDS (rhythm/connective inspiration only — NOT facts):
${seeds}

Rewrite the span now. Output only the rewritten text.`;

const MODEL = $vars && $vars.PB_CLAUDE_MODEL ? $vars.PB_CLAUDE_MODEL : "claude-sonnet-4-6";
const TEMPERATURE = 0.4;

// ---- deterministic seeded PRNG (sha256 -> mulberry32) ----------------------
const crypto = require("crypto");
function seedFrom(text, salt) {
  const h = crypto.createHash("sha256").update((salt || "") + "::" + text).digest("hex");
  return parseInt(h.slice(0, 8), 16) >>> 0;
}
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const WORD_RE = /[A-Za-z0-9']+/g;

// ---- compact Markov (span + optional corpus subset) ------------------------
function buildChain(text, corpusPhrases) {
  const order = 2;
  const chain = {};
  const starts = [];
  const train = (t) => {
    for (const sent of t.trim().split(/(?<=[.!?])\s+/)) {
      const toks = sent.match(WORD_RE) || [];
      if (toks.length < order + 1) continue;
      starts.push(toks.slice(0, order));
      for (let i = 0; i < toks.length - order; i++) {
        const key = toks.slice(i, i + order).join(" ");
        (chain[key] = chain[key] || []).push(toks[i + order]);
      }
    }
  };
  train(text); train(text); // weight span twice
  if (corpusPhrases) for (const p of corpusPhrases) train(p);
  return { chain, starts, order };
}
function cadenceSeeds(spanText, mk, n = 5, minLen = 2, maxLen = 6) {
  if (!mk.starts.length) return [];
  const rnd = mulberry32(seedFrom(spanText, ""));
  const ri = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));
  const out = [], seen = new Set();
  let attempts = 0;
  while (out.length < n && attempts < n * 8) {
    attempts++;
    const target = ri(minLen, maxLen);
    const key = mk.starts[Math.floor(rnd() * mk.starts.length)];
    const words = key.slice();
    let cur = key.join(" ");
    while (words.length < target) {
      const ch = mk.chain[cur];
      if (!ch || !ch.length) break;
      const nxt = ch[Math.floor(rnd() * ch.length)];
      words.push(nxt);
      cur = words.slice(-mk.order).join(" ");
    }
    const frag = words.join(" ").trim(), low = frag.toLowerCase();
    if (words.length >= minLen && frag && !seen.has(low)) { seen.add(low); out.push(frag); }
  }
  return out;
}
function paragraphShape(spanText) {
  const rnd = mulberry32(seedFrom(spanText, "shape:"));
  const ri = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));
  const nPara = ri(1, 3);
  const shape = [];
  for (let i = 0; i < nPara; i++) shape.push(ri(1, 5));
  return { paragraphs: nPara, sentences_per_paragraph: shape };
}

// ---- main ------------------------------------------------------------------
const report = $input.first().json;
const fullText = report.text || "";

// NOTE ON MARKOV SOURCE (intentional difference from the Python reference):
// The Python engine also trains on dictionary/human_corpus.json (2,307 human
// travel sentences). Inlining 100KB+ into a Code node is impractical, and the
// cadence seeds are "rhythm inspiration only" — never facts (the deterministic
// fact-guard downstream rejects any new number/entity regardless of seed source).
// So the native node trains the Markov on the SPAN'S OWN TEXT only. Seeds stay
// deterministic (seeded PRNG) and on-topic; safety is unchanged.
const corpus = null;

if (!report.flagged || !report.flagged_spans || !report.flagged_spans.length) {
  return [{ json: { __passthrough: true, original_text: fullText, flagged: false,
    phase1: report } }];
}

const items = [];
report.flagged_spans.forEach((sp, idx) => {
  const spanText = fullText.slice(sp.start, sp.end);
  const mk = buildChain(spanText, corpus);
  const seeds = cadenceSeeds(spanText, mk);
  const shape = paragraphShape(spanText);
  const reasons = (sp.reasons && sp.reasons.length ? sp.reasons : ["Mechanical pattern detected."])
    .map(r => "- " + r).join("\n");
  const shapeStr = `${shape.paragraphs} paragraph(s); sentences each: [${shape.sentences_per_paragraph.join(", ")}]`;
  const seedStr = seeds.length ? seeds.map(s => "• " + s).join("\n") : "(none available)";
  const userMsg = USER_TEMPLATE(spanText, reasons, shapeStr, seedStr);

  items.push({ json: {
    __passthrough: false,
    span_index: idx,
    span_start: sp.start,
    span_end: sp.end,
    factors: sp.factors || [],
    original_span: spanText,
    original_text: fullText,
    anthropicPayload: {
      model: MODEL,
      max_tokens: 1024,
      temperature: TEMPERATURE,
      system: SYSTEM_PROMPT,
      messages: [{ role: "user", content: userMsg }]
    }
  }});
});
return items;

// ============================================================================
// Pattern Breaker — Phase 2 finalize (n8n Code node, run once for all items)
// Input: all span items, each with .original_span, .span_start/.end, and the
//        Claude HTTP response merged in (json.content[].text).
// Does: deterministic fact-guard (port of restructurer/factguard.py) per span,
//       applies light-blue highlight to major-change spans, stitches spans back
//       into the full document (HTML + plaintext-marker variants), and reports.
// If the upstream was a passthrough (nothing flagged), returns original unchanged.
// ============================================================================

const HL_OPEN_HTML = '<span class="pb-review" style="background-color:#cfe8ff">';
const HL_CLOSE_HTML = "</span>";
const HL_OPEN_MD = "[[PB-REVIEW]]";
const HL_CLOSE_MD = "[[/PB-REVIEW]]";

// ---- factguard port --------------------------------------------------------
const WORD = /[A-Za-z][A-Za-z'\-]*/g;
const NUMBER_CTX = /\b(\d[\d,\.]*)\s*([A-Za-z%$€£]+)?/g;
const NUM_WORDS = { zero:"0",one:"1",two:"2",three:"3",four:"4",five:"5",six:"6",seven:"7",eight:"8",nine:"9",ten:"10",eleven:"11",twelve:"12",thirteen:"13",fourteen:"14",fifteen:"15",sixteen:"16",seventeen:"17",eighteen:"18",nineteen:"19",twenty:"20",thirty:"30",forty:"40",fifty:"50",sixty:"60",seventy:"70",eighty:"80",ninety:"90",hundred:"100",thousand:"1000" };
const AMBIGUOUS = new Set(["one"]);
const COMMON = new Set(["The","A","An","This","That","These","Those","It","We","You","They","He","She","I","Our","Your","Their","His","Her","But","And","Or","So","Then","When","While","If","As","For","In","On","At","To","Of","With","From","By","Also","Here","There","Now","One","Two","Three","Bring","Get","Go","Come","Every","Each","Moreover","Furthermore","Additionally","Overall","Ultimately"]);

function numbers(text) {
  const out = new Set(); let m;
  NUMBER_CTX.lastIndex = 0;
  while ((m = NUMBER_CTX.exec(text)) !== null) out.add(m[1].replace(/,/g, ""));
  const ws = (text.toLowerCase().match(WORD) || []);
  for (const w of ws) if (NUM_WORDS[w] && !AMBIGUOUS.has(w)) out.add(NUM_WORDS[w]);
  return out;
}
function entities(text) {
  const ents = new Set();
  for (const sent of text.trim().split(/(?<=[.!?])\s+/)) {
    const toks = sent.match(WORD) || [];
    toks.forEach((w, i) => {
      if (!/[A-Z]/.test(w[0])) return;
      if (i === 0) return;
      if (COMMON.has(w)) return;
      if (w === w.toUpperCase() && w.length <= 3) return;
      ents.add(w);
    });
  }
  return ents;
}
const diff = (a, b) => [...a].filter(x => !b.has(x)).sort();
function guard(original, rewrite) {
  const on = numbers(original), rn = numbers(rewrite);
  const oe = entities(original), re_ = entities(rewrite);
  const newNums = diff(rn, on), newEnts = diff(re_, oe);
  const dropNums = diff(on, rn), dropEnts = diff(oe, re_);
  const hardFail = newNums.length || newEnts.length;
  const major = dropNums.length || dropEnts.length;
  const parts = [];
  if (newNums.length) parts.push(`introduced numbers ${JSON.stringify(newNums)}`);
  if (newEnts.length) parts.push(`introduced entities ${JSON.stringify(newEnts)}`);
  if (dropNums.length) parts.push(`dropped numbers ${JSON.stringify(dropNums)}`);
  if (dropEnts.length) parts.push(`dropped entities ${JSON.stringify(dropEnts)}`);
  return { ok: !hardFail, major_change: !!major,
    new_numbers: newNums, new_entities: newEnts,
    dropped_numbers: dropNums, dropped_entities: dropEnts,
    reason: parts.length ? parts.join("; ") : "clean" };
}
function extractText(json) {
  if (!json) return "";
  if (Array.isArray(json.content))
    return json.content.filter(b => b.type === "text").map(b => b.text).join("").trim();
  if (typeof json.text === "string") return json.text.trim();
  return "";
}

// ---- gather items ----------------------------------------------------------
// The HTTP node returns ONLY Claude's response body per item and drops the input
// fields, so we re-read each span's metadata from the "Prepare Spans" node by the
// SAME item index (n8n keeps item order 1:1 through the HTTP node). This makes the
// stitch robust regardless of the HTTP node's field-passing behaviour.
const httpItems = $input.all().map(i => i.json);
const prep = $("Prepare Spans").all().map(i => i.json);

// passthrough (nothing was flagged) — detected on the Prepare Spans output
const pass = prep.find(j => j.__passthrough);
if (pass) {
  const text = pass.original_text || "";
  return [{ json: {
    changed: false, needs_human_review: false, flags_cleared: true,
    output_text: text, output_html: text.replace(/\n/g, "<br>\n"),
    span_results: [], phase1: pass.phase1 || null,
    note: "No mechanical pattern detected; text returned unchanged."
  }}];
}

// pair each prepared span with its Claude response by index
const paired = prep
  .map((p, idx) => ({ p, http: httpItems[idx] }))
  .filter(x => x.p && x.p.span_start !== undefined)
  .sort((a, b) => a.p.span_start - b.p.span_start);
const originalText = (paired[0] && paired[0].p.original_text) || "";

const results = [];
for (const { p, http } of paired) {
  const s = p;
  const rewrite = extractText(http);           // Claude output for this span
  const original = s.original_span;
  let accepted = false, needsReview = false, majorChange = false, reason = "no output";
  let finalText = original;
  if (rewrite) {
    const g = guard(original, rewrite);
    reason = g.reason;
    if (g.ok) { accepted = true; finalText = rewrite; majorChange = g.major_change; needsReview = g.major_change; }
    else { accepted = false; finalText = original; needsReview = true; }  // hard fail -> keep original, flag
  } else { needsReview = true; }
  results.push({ start: s.span_start, end: s.span_end, factors: s.factors,
    original, rewrite, accepted, major_change: majorChange,
    needs_human_review: needsReview, guard_reason: reason });
}

// ---- stitch (walk original, replace accepted spans, highlight majors) -------
function stitch(highlight) {
  const open = highlight === "html" ? HL_OPEN_HTML : HL_OPEN_MD;
  const close = highlight === "html" ? HL_CLOSE_HTML : HL_CLOSE_MD;
  let out = "", cursor = 0;
  for (const r of results) {
    out += originalText.slice(cursor, r.start);
    let piece = r.accepted ? r.rewrite : r.original;
    if (r.needs_human_review) piece = open + piece + close;
    out += piece;
    cursor = r.end;
  }
  out += originalText.slice(cursor);
  return out;
}
const outputPlain = stitch("md");
const outputHtml = stitch("html").replace(/\n/g, "<br>\n");

const needsHuman = results.some(r => r.needs_human_review);
return [{ json: {
  changed: results.some(r => r.accepted),
  needs_human_review: needsHuman,
  output_text: outputPlain,
  output_html: outputHtml,
  span_results: results,
  summary: {
    spans_total: results.length,
    spans_accepted: results.filter(r => r.accepted).length,
    spans_flagged_for_review: results.filter(r => r.needs_human_review).length
  }
}}];
